/**
 * One-time import of the offline Ahrefs keyword master CSV into the DB.
 *
 * Reads docs/seo-ahrefs-outputs/keyword_master.csv (generated by
 * scripts/seo-ahrefs-pipeline.cjs) and upserts each row into:
 *   - SeoKeyword   (static snapshot, unique per keyword)
 *   - KeywordRank  (position on today's IST date, for the position-history chart)
 *
 * Run: npm run seo:import   (requires DATABASE_URL in the environment / .env)
 */
const fs = require('fs');
const path = require('path');
const { PrismaClient } = require('@prisma/client');

const CSV_PATH = path.join(__dirname, '..', 'docs', 'seo-ahrefs-outputs', 'keyword_master.csv');

function todayIst() {
    return new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Kolkata',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
    }).format(new Date());
}

/** Minimal CSV parser that respects double-quoted fields. */
function parseCsv(text) {
    const rows = [];
    let row = [];
    let field = '';
    let inQuotes = false;
    for (let i = 0; i < text.length; i++) {
        const ch = text[i];
        if (inQuotes) {
            if (ch === '"') {
                if (text[i + 1] === '"') {
                    field += '"';
                    i++;
                } else {
                    inQuotes = false;
                }
            } else {
                field += ch;
            }
        } else if (ch === '"') {
            inQuotes = true;
        } else if (ch === ',') {
            row.push(field);
            field = '';
        } else if (ch === '\n' || ch === '\r') {
            if (ch === '\r' && text[i + 1] === '\n') i++;
            if (field !== '' || row.length) {
                row.push(field);
                rows.push(row);
            }
            field = '';
            row = [];
        } else {
            field += ch;
        }
    }
    if (field !== '' || row.length) {
        row.push(field);
        rows.push(row);
    }
    return rows;
}

function toInt(v) {
    const n = parseInt(String(v ?? '').trim(), 10);
    return Number.isFinite(n) ? n : null;
}
function toFloat(v) {
    const n = parseFloat(String(v ?? '').trim());
    return Number.isFinite(n) ? n : null;
}

async function main() {
    if (!fs.existsSync(CSV_PATH)) {
        console.log(`[seo:import] ${CSV_PATH} not found — nothing to import.`);
        process.exit(0);
    }
    const text = fs.readFileSync(CSV_PATH, 'utf8');
    const rows = parseCsv(text);
    if (rows.length < 2) {
        console.log('[seo:import] No data rows in keyword_master.csv.');
        process.exit(0);
    }

    const header = rows[0].map((h) => h.trim());
    const snapshotDate = todayIst();
    const db = new PrismaClient();

    let imported = 0;
    try {
        for (const row of rows.slice(1)) {
            const record = Object.fromEntries(header.map((h, i) => [h, row[i]]));
            const keyword = String(record.keyword ?? '').trim();
            if (!keyword) continue;

            const seoData = {
                pagePath: record.page_path ? String(record.page_path) : null,
                market: record.market ? String(record.market) : null,
                intent: record.intent ? String(record.intent) : null,
                painPoint: record.pain_point ? String(record.pain_point) : null,
                businessFit: record.business_fit ? String(record.business_fit) : null,
                pageBucket: record.page_bucket ? String(record.page_bucket) : null,
                mappedUrl: record.mapped_url ? String(record.mapped_url) : null,
                position: toInt(record.position),
                volume: toInt(record.volume),
                kd: toFloat(record.kd),
                traffic: toInt(record.traffic),
                priorityScore: toInt(record.priority_score),
                sourceFile: 'keyword_master.csv',
            };

            await db.seoKeyword.upsert({
                where: { keyword },
                create: { keyword, ...seoData },
                update: seoData,
            });

            await db.keywordRank.upsert({
                where: { keyword_snapshotDate: { keyword, snapshotDate } },
                create: {
                    keyword,
                    position: seoData.position ?? 0,
                    volume: seoData.volume,
                    kd: seoData.kd,
                    traffic: seoData.traffic,
                    snapshotDate,
                    notes: 'Ahrefs import',
                },
                update: {},
            });
            imported++;
        }
        console.log(`[seo:import] Imported/updated ${imported} keywords (snapshot ${snapshotDate}).`);
    } finally {
        await db.$disconnect();
    }
}

main().catch((err) => {
    console.error('[seo:import] Failed:', err);
    process.exit(1);
});
